#[test]fn node_scope_accepts_documented_contract_types_without_dropping_context_or_leaf_checks(){
 let server=Server::new(vec![]);let dir=temp();{
 let t=transport(&dir,&server,false,Arc::new(AtomicU64::new(1000)));
 let original=json!({"market_id":"305","contexts":[{"type":"tournament","tournament":{"id":"bda92870-621e-47b0-bc3c-3602c5c26f55"}}],"root":{"node_id":"101","contract_id":"101","node_type":"contract","contract_type":"Freeform"}});
 for contract_type in [json!("Freeform"),json!("Election Outcome"),Value::Null]{let mut v=original.clone();v["root"]["contract_type"]=contract_type;t.validate(&Endpoint::Nodes{market_id:"305".into()},&v).unwrap();}
 let mut wrong=original.clone();wrong["market_id"]=json!("306");assert!(t.validate(&Endpoint::Nodes{market_id:"305".into()},&wrong).is_err());
 let mut wrong=original.clone();wrong["contexts"][0]["tournament"]["id"]=json!("other");assert!(t.validate(&Endpoint::Nodes{market_id:"305".into()},&wrong).is_err());
 let mut wrong=original;wrong["root"]["node_type"]=json!("operator");assert!(t.validate(&Endpoint::Nodes{market_id:"305".into()},&wrong).is_err());
 }fs::remove_dir_all(dir).unwrap();
}
fn ack()->String{json!({"orderId":42,"exchangeId":"994","open":true,"remainingQuantity":1,"quantity":1,"quantityTraded":0,"totalCost":0,"fillPrice":null,"price":0.12,"side":"no","action":"buy","all":{}}).to_string()}
#[test]fn ack_advisory_totals_do_not_credit_fills_or_lose_the_original_evidence(){for mode in 0..3{let mut v:Value=serde_json::from_str(&ack()).unwrap();match mode{0=>{v["remainingQuantity"]=json!(0);},1=>{v["remainingQuantity"]=json!(-1);},_=>{v.as_object_mut().unwrap().remove("remainingQuantity");v.as_object_mut().unwrap().remove("all");}}let server=Server::new(vec![(200,vec![],v.to_string())]);let dir=temp();{let mut t=transport(&dir,&server,true,Arc::new(AtomicU64::new(1000)));let r=t.place(order(),permit("advisory")).unwrap();assert_eq!(r.data,v);assert_eq!(t.admission_state().unwrap()["state"]["unknown"],json!({}));let files:Vec<_>=fs::read_dir(&dir).unwrap().filter_map(|p|{let p=p.unwrap().path();p.file_name().unwrap().to_string_lossy().starts_with("write-response-").then_some(p)}).collect();assert_eq!(files.len(),1);let stored:Value=serde_json::from_slice(&fs::read(&files[0]).unwrap()).unwrap();assert_eq!(stored["data"],v);assert!(stored.get("headers").is_none());}fs::remove_dir_all(dir).unwrap();}}
#[test]fn inconsistent_admission_size_and_out_of_bound_advisory_quantity_remain_unknown(){for mode in 0..3{let mut v:Value=serde_json::from_str(&ack()).unwrap();match mode{0=>v["quantity"]=json!(2),1=>v["price"]=json!(0.125),_=>v["quantityTraded"]=json!(-2)}let server=Server::new(vec![(200,vec![],v.to_string())]);let dir=temp();{let mut t=transport(&dir,&server,true,Arc::new(AtomicU64::new(1000)));assert!(t.place(order(),permit("invalid")).err().unwrap().may_have_executed);assert_eq!(t.admission_state().unwrap()["state"]["unknown"].as_object().unwrap().len(),1);assert!(fs::read_dir(&dir).unwrap().any(|p|p.unwrap().file_name().to_string_lossy().starts_with("write-response-")));}fs::remove_dir_all(dir).unwrap();}}
#[test]fn documented_null_relationship_economics_does_not_make_a_valid_order_unknown(){let mut value:Value=serde_json::from_str(&ack()).unwrap();value["all"]=Value::Null;let server=Server::new(vec![(200,vec![],value.to_string())]);let dir=temp();{let mut t=transport(&dir,&server,true,Arc::new(AtomicU64::new(1000)));let r=t.place(order(),permit("nullable-all")).unwrap();assert_eq!(r.data["orderId"],42);assert_eq!(t.admission_state().unwrap()["state"]["unknown"],json!({}));}fs::remove_dir_all(dir).unwrap();}

#[test]fn decimal_money_is_exact_and_never_rounded(){assert_eq!(decimal_units("100000.123456").unwrap(),100000123456);assert_eq!(decimal_units("-0.005000").unwrap(),-5000);assert!(decimal_units("0.0000001").is_err());assert_eq!(decimal_units("1e-6").unwrap(),1);assert_eq!(decimal_units("5e-3").unwrap(),5000);assert_eq!(decimal_units("1e+5").unwrap(),100000000000);assert_eq!(decimal_units("0.12000000").unwrap(),120000);assert!(decimal_units("1.2345671").is_err());assert!(decimal_units("1e9999").is_err());}
