#[test]fn uncertain503_persists_unknown_acceptance_and_backoff_across_restart(){let server=Server::new(vec![(503,vec![("Retry-After","90")],r#"{"error":{"code":"SERVICE_UNAVAILABLE"}}"#.into()),(200,vec![],tournament())]);let dir=temp();let clock=Arc::new(AtomicU64::new(1000));{let mut t=transport(&dir,&server,true,clock.clone());let e=t.place(order(),permit("one")).err().unwrap();assert!(e.may_have_executed);assert_eq!(t.admission_state().unwrap()["state"]["cooldown"],91000);} {let mut t=transport(&dir,&server,true,clock.clone());let mut replacement=order();replacement.idempotency_key="different".into();assert_eq!(t.place(replacement,permit("replacement")).err().unwrap().code,"UNKNOWN_ACCEPTANCE_RECONCILE_FIRST");t.request(Endpoint::Tournament).unwrap();assert_eq!(clock.load(Ordering::SeqCst),91000);}assert_eq!(server.requests.lock().unwrap().len(),2);fs::remove_dir_all(dir).unwrap();}
#[test]fn malformed_success_preserves_returned_order_id_and_unknown_fence(){let server=Server::new(vec![(200,vec![],ack().replace("\"no\"","\"yes\""))]);let dir=temp();{let mut t=transport(&dir,&server,true,Arc::new(AtomicU64::new(1000)));let e=t.place(order(),permit("one")).err().unwrap();assert!(e.may_have_executed);assert_eq!(e.order_id.as_deref(),Some("42"));assert_eq!(t.admission_state().unwrap()["state"]["unknown"].as_object().unwrap().len(),1);}fs::remove_dir_all(dir).unwrap();}
